#!/usr/bin/env bun
/**
 * Reproducible headless Chromium / Edge WebGPU + DOM + ARIA + screenshot verifier.
 * Serves `target/web-dist` (generated by `tooling/bun/web-build.ts`) on `127.0.0.1:0`,
 * asserts live GPU initialization, non-zero `<canvas role="application">`, 0 uncaught JS errors,
 * and saves PNG proof under gitignored `target/web-screenshots/<pkg>.png`.
 *
 * Usage:
 *   bun tooling/bun/web-verify.ts [--package aphrody_desktop] [--out-dir target/web-dist] [--shot target/web-screenshots/aphrody_desktop.png]
 */
import { existsSync, mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { extname, join, resolve } from "node:path";
import { tmpdir } from "node:os";

const repoRoot = resolve(import.meta.dir, "../..");

function opt(flag: string): string | undefined {
  const args = Bun.argv.slice(2);
  const idx = args.indexOf(flag);
  if (idx >= 0) return args[idx + 1];
  const eq = args.find((a) => a.startsWith(`${flag}=`));
  return eq ? eq.slice(flag.length + 1) : undefined;
}

function findBrowserExecutable(): string {
  const fromEnv = process.env.APHRODY_CHROME_BIN ?? process.env.CHROME_BIN;
  if (fromEnv && existsSync(fromEnv)) return fromEnv;

  const candidates =
    process.platform === "win32"
      ? [
          "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe",
          "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe",
        ]
      : [
          "/usr/bin/google-chrome",
          "/usr/bin/chromium",
          "/usr/bin/chromium-browser",
          "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
        ];

  for (const candidate of candidates) {
    if (existsSync(candidate)) return candidate;
  }
  throw new Error("No Chromium/Chrome/Edge executable found; set APHRODY_CHROME_BIN or CHROME_BIN.");
}

const pkg = opt("--package") ?? "aphrody_desktop";
const metaRes = Bun.spawnSync(["cargo", "metadata", "--no-deps", "--format-version", "1"], {
  cwd: repoRoot,
  stdout: "pipe",
  stderr: "pipe",
});
const targetDir =
  metaRes.exitCode === 0
    ? (JSON.parse(new TextDecoder().decode(metaRes.stdout)) as { target_directory: string }).target_directory
    : join(repoRoot, "target");

const distDir = resolve(opt("--out-dir") ?? join(targetDir, "web-dist"));
const shotOut = resolve(opt("--shot") ?? join(targetDir, "web-screenshots", `${pkg}.png`));
if (!existsSync(join(distDir, "index.html"))) {
  throw new Error(`Missing ${join(distDir, "index.html")}; run \`bun tooling/bun/web-build.ts build --package ${pkg} --opt\` first.`);
}

const mimeMap: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".mjs": "text/javascript; charset=utf-8",
  ".wasm": "application/wasm",
  ".json": "application/json; charset=utf-8",
};

const server = Bun.serve({
  hostname: "127.0.0.1",
  port: 0,
  async fetch(req) {
    const pathname = new URL(req.url).pathname;
    const rel = pathname === "/" ? "/index.html" : pathname;
    const filePath = resolve(distDir, `.${rel}`);
    if (!filePath.startsWith(distDir)) return new Response("Forbidden", { status: 403 });
    const file = Bun.file(filePath);
    if (!(await file.exists())) return new Response("Not Found", { status: 404 });
    return new Response(file, {
      headers: { "Content-Type": mimeMap[extname(filePath)] ?? "application/octet-stream" },
    });
  },
});

const profileDir = mkdtempSync(join(tmpdir(), "aphrody-webgpu-"));
const chromePath = findBrowserExecutable();
const proc = Bun.spawn(
  [
    chromePath,
    "--headless=new",
    "--remote-debugging-port=0",
    `--user-data-dir=${profileDir}`,
    "--window-size=1280,800",
    "--enable-unsafe-webgpu",
    "--enable-webgl",
    "--disable-gpu-sandbox",
    "--no-first-run",
    "--no-default-browser-check",
    `http://127.0.0.1:${server.port}/`,
  ],
  { stdout: "pipe", stderr: "pipe" },
);

async function readWsUrl(): Promise<string> {
  const deadline = Date.now() + 10_000;
  const reader = proc.stderr.getReader();
  let buf = "";
  while (Date.now() < deadline) {
    const { value, done } = await reader.read();
    if (done) break;
    buf += new TextDecoder().decode(value);
    const match = buf.match(/DevTools listening on (ws:\/\/[^\s]+)/);
    if (match) return match[1];
  }
  throw new Error(`Chrome DevTools WS not found. stderr=${buf}`);
}

let exitCode = 0;
try {
  const browserWs = await readWsUrl();
  const baseHttp = browserWs.replace(/^ws:/, "http:").replace(/\/devtools\/browser\/.*$/, "");
  let pageWs = "";
  for (let i = 0; i < 30; i++) {
    const targets = (await fetch(`${baseHttp}/json/list`).then((r) => r.json())) as Array<{
      type: string;
      webSocketDebuggerUrl: string;
    }>;
    const page = targets.find((t) => t.type === "page");
    if (page?.webSocketDebuggerUrl) {
      pageWs = page.webSocketDebuggerUrl;
      break;
    }
    await Bun.sleep(150);
  }
  if (!pageWs) throw new Error("No page target found in headless browser");

  const ws = new WebSocket(pageWs);
  await new Promise<void>((res, rej) => {
    ws.onopen = () => res();
    ws.onerror = (err) => rej(err);
  });

  let nextId = 1;
  const pending = new Map<number, { resolve: (v: unknown) => void; reject: (e: unknown) => void }>();
  const exceptions: string[] = [];
  const consoleLogs: string[] = [];

  ws.onmessage = (ev) => {
    const msg = JSON.parse(String(ev.data)) as { id?: number; method?: string; result?: unknown; error?: unknown; params?: any };
    if (msg.id && pending.has(msg.id)) {
      const p = pending.get(msg.id)!;
      pending.delete(msg.id);
      if (msg.error) p.reject(msg.error);
      else p.resolve(msg.result);
    } else if (msg.method === "Runtime.exceptionThrown") {
      exceptions.push(JSON.stringify(msg.params?.exceptionDetails ?? msg.params));
    } else if (msg.method === "Runtime.consoleAPICalled") {
      const txt = (msg.params?.args ?? []).map((a: any) => a.value ?? a.description ?? "").join(" ");
      consoleLogs.push(`[${msg.params?.type}] ${txt}`);
    }
  };

  function cdp(method: string, params: Record<string, unknown> = {}): Promise<any> {
    const id = nextId++;
    return new Promise((resolvePromise, rejectPromise) => {
      pending.set(id, { resolve: resolvePromise, reject: rejectPromise });
      ws.send(JSON.stringify({ id, method, params }));
    });
  }

  await cdp("Page.enable");
  await cdp("Runtime.enable");

  let domState: any = null;
  for (let i = 0; i < 60; i++) {
    const res = await cdp("Runtime.evaluate", {
      expression: `(() => {
        const st = document.getElementById("a11y-status");
        const canvases = Array.from(document.querySelectorAll("canvas")).map(c => ({
          role: c.getAttribute("role"),
          ariaLabel: c.getAttribute("aria-label"),
          width: c.width,
          height: c.height,
        }));
        return {
          title: document.title,
          statusText: st?.textContent ?? null,
          backend: st?.getAttribute("data-backend") ?? null,
          cohort: st?.getAttribute("data-cohort") ?? null,
          loaded: st?.getAttribute("data-loaded") ?? null,
          error: st?.getAttribute("data-error") ?? null,
          canvases,
        };
      })()`,
      returnByValue: true,
    });
    domState = res?.result?.value;
    if (domState?.loaded === "true" && domState?.canvases?.length > 0 && domState.canvases[0].width > 100) {
      await Bun.sleep(600);
      break;
    }
    if (domState?.error) break;
    await Bun.sleep(250);
  }

  const shot = await cdp("Page.captureScreenshot", { format: "png" });
  mkdirSync(resolve(shotOut, ".."), { recursive: true });
  writeFileSync(shotOut, Buffer.from(shot.data, "base64"));

  console.log(JSON.stringify({ domState, consoleCount: consoleLogs.length, exceptions, screenshot: shotOut }, null, 2));
  if (
    domState?.error ||
    exceptions.length > 0 ||
    !domState?.canvases?.length ||
    domState.canvases[0].width < 100 ||
    domState.canvases[0].height < 100
  ) {
    exitCode = 1;
  }
  ws.close();
} finally {
  proc.kill();
  await proc.exited.catch(() => {});
  server.stop();
  rmSync(profileDir, { recursive: true, force: true });
}
process.exit(exitCode);
